beforeExample:
class Example {
    String process(String input) {
        // Replacing literal '' with ' using replaceAll
        return input.replaceAll("''", "'");
    }
}

afterExample:
class Example {
    String process(String input) {
        // Using replace is more direct for literal string replacement
        return input.replace("''", "'");
    }
}

negativeExample:
class Example {
    String process(String input) {
        // This should not be converted as "." is a regex special character
        return input.replaceAll(".", "X");
    }
}
